import{n as t}from"./index-CO_1ZYTr.js";const r={async getAllPayments(e){return(await t.get("/payments",{params:e})).data},async getPaymentStats(){return(await t.get("/payments/admin/stats")).data},async createPayment(e){return(await t.post("/payments",e)).data},async approvePayment(e,s=!1){return(await t.put(`/payments/${e}/approve`,{isInstallment:s})).data},async deletePayment(e){return(await t.delete(`/payments/${e}`)).data},async getUserPayments(e){return(await t.get(`/payments/user/${e}`)).data},async confirmPayment(e,s=!1){return(await t.put(`/payments/${e}/confirm`,{isInstallment:s})).data}};export{r as P};
